/**
 * Validates the committed docs site under `docs-site/`.
 *
 * The site is generated by the shared Docs tool (`scripts/build-docs.sh`) and, unlike every other
 * consumer's, it is tracked rather than gitignored. Tracked generated output can go stale in ways
 * markdown cannot: a version directory removed by hand, a manifest naming a release that is not
 * there, a stylesheet lost in a bad merge. Nothing else in the repo would notice.
 *
 * It also holds the generator to the one promise a reader cannot check for themselves -- that the
 * site fetches nothing at page load.
 */
import { join } from '@std/path';

/** A host that would make the site fetch something at page load. */
const CDN_HOSTS = ['jsdelivr', 'googleapis', 'gstatic', 'unpkg', 'cdnjs'];

export interface VersionEntry {
  prefix: string;
  tag: string | null;
  release: boolean;
  built: string;
}

export interface Manifest {
  versions: VersionEntry[];
  latest: string;
}

/** Parses a manifest, returning the problems with it rather than throwing on the first. */
export function manifestProblems(text: string): string[] {
  let parsed: unknown;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    return [`versions.json is not valid JSON: ${(e as Error).message}`];
  }
  const m = parsed as Partial<Manifest>;
  const problems: string[] = [];
  if (!Array.isArray(m.versions)) problems.push('versions.json has no versions array');
  if (typeof m.latest !== 'string' || m.latest.length === 0) {
    problems.push('versions.json has no latest');
  }
  if (Array.isArray(m.versions) && typeof m.latest === 'string') {
    if (!m.versions.some((v) => v?.prefix === m.latest)) {
      problems.push(`versions.json names latest "${m.latest}", which is not one of its versions`);
    }
    for (const v of m.versions) {
      if (typeof v?.prefix !== 'string' || v.prefix.length === 0) {
        problems.push('a version entry has no prefix');
      }
      if (v?.release === true && (typeof v.tag !== 'string' || v.tag.length === 0)) {
        problems.push(`version "${v?.prefix}" claims to be a release but carries no tag`);
      }
    }
  }
  return problems;
}

async function isFile(path: string): Promise<boolean> {
  try {
    return (await Deno.stat(path)).isFile;
  } catch {
    return false;
  }
}

async function* filesUnder(dir: string): AsyncGenerator<string> {
  for await (const e of Deno.readDir(dir)) {
    const path = join(dir, e.name);
    if (e.isDirectory) yield* filesUnder(path);
    else if (e.isFile) yield path;
  }
}

/** Every file whose text names a CDN host. Binary files are skipped, not decoded. */
export async function cdnReferences(root: string): Promise<string[]> {
  const hits: string[] = [];
  for await (const path of filesUnder(root)) {
    if (!/\.(html|css|js|json|svg)$/i.test(path)) continue;
    const text = await Deno.readTextFile(path);
    if (CDN_HOSTS.some((h) => text.includes(h))) hits.push(path);
  }
  return hits;
}

/** Every problem with the site at `root`. An empty list means it is intact. */
export async function siteProblems(root: string): Promise<string[]> {
  const problems: string[] = [];

  const manifestPath = join(root, 'versions.json');
  if (!await isFile(manifestPath)) return [`${manifestPath} is missing -- has the site been built?`];
  if (!await isFile(join(root, 'index.html'))) problems.push(`${root}/index.html is missing`);

  const text = await Deno.readTextFile(manifestPath);
  problems.push(...manifestProblems(text));
  if (problems.some((p) => p.startsWith('versions.json is not valid JSON'))) return problems;

  const manifest = JSON.parse(text) as Manifest;
  for (const v of manifest.versions ?? []) {
    if (typeof v?.prefix !== 'string') continue;
    for (const required of ['index.html', 'site.css']) {
      const path = join(root, v.prefix, required);
      if (!await isFile(path)) problems.push(`${path} is missing, but versions.json lists it`);
    }
  }

  for (const path of await cdnReferences(root)) {
    problems.push(`${path} references a CDN -- the site must fetch nothing at page load`);
  }
  return problems;
}

if (import.meta.main) {
  const root = Deno.args[0] ?? 'docs-site';
  const problems = await siteProblems(root);
  for (const p of problems) console.error(`ERROR: ${p}`);
  if (problems.length > 0) {
    console.error(`${problems.length} problem(s) in ${root}`);
    Deno.exit(1);
  }
  console.log(`${root} is intact`);
}
